// sidepanel/ai/tool-executor.js
// Executes tool calls generated by the AI agent against the Brave/Chrome extension APIs and page DOM.
// Plain script (no import/export) — exposes window.SidebarAI.executeTool.
'use strict';

(function (global) {
  async function executeTool(toolName, args = {}) {
    try {
      switch (toolName) {
        // --- Page & DOM Tools ---
        case 'read_current_page':
          return await executeInActiveTab('READ_PAGE', args);
        case 'get_page_elements':
          return await executeInActiveTab('GET_PAGE_ELEMENTS', args);
        case 'click_element':
          return await executeInActiveTab('CLICK_ELEMENT', args);
        case 'fill_form_field':
          return await executeInActiveTab('FILL_FORM_FIELD', args);
        case 'scroll_page':
          return await executeInActiveTab('SCROLL_PAGE', args);
        case 'execute_page_script':
          return await executeInActiveTab('EXECUTE_PAGE_SCRIPT', args);
        case 'capture_screenshot':
          return await captureScreenshot();

        // --- Tabs & Windows ---
        case 'list_tabs':
          return await listTabs(args);
        case 'switch_tab':
          return await switchTab(args.tab_id);
        case 'create_tab':
          return await createTab(args.url, args.active ?? true);
        case 'close_tabs':
          return await closeTabs(args.tab_ids);
        case 'duplicate_tab':
          return await duplicateTab(args.tab_id);
        case 'pin_tab':
          return await pinTab(args.tab_id, args.pinned);
        case 'mute_tab':
          return await muteTab(args.tab_id, args.muted);
        case 'group_tabs':
          return await groupTabs(args.tab_ids, args.title, args.color);
        case 'set_zoom':
          return await setZoom(args.zoom_factor, args.tab_id);

        // --- History & Bookmarks ---
        case 'search_history':
          return await searchHistory(args.text, args.max_results, args.start_days_ago);
        case 'delete_history_url':
          return await deleteHistoryUrl(args.url);
        case 'search_bookmarks':
          return await searchBookmarks(args.query);
        case 'create_bookmark':
          return await createBookmark(args.title, args.url, args.parent_id);
        case 'get_top_sites':
          return await getTopSites();

        // --- Extensions ---
        case 'list_extensions':
          return await listExtensions();
        case 'set_extension_enabled':
          return await setExtensionEnabled(args.extension_id, args.enabled);
        case 'uninstall_extension':
          return await uninstallExtension(args.extension_id);

        // --- Privacy & Browsing Data ---
        case 'clear_browsing_data':
          return await clearBrowsingData(args.timeframe, args.data_types);
        case 'get_privacy_settings':
          return await getPrivacySettings();
        case 'set_privacy_setting':
          return await setPrivacySetting(args.setting_name, args.value);
        case 'get_content_settings':
          return await getContentSettings(args.content_type);
        case 'set_content_settings':
          return await setContentSettings(args.content_type, args.setting, args.scope);

        // --- Downloads ---
        case 'download_file':
          return await downloadFile(args.filename, args.content, args.url);
        case 'search_downloads':
          return await searchDownloads(args.query, args.limit);

        default:
          return { success: false, error: `Ferramenta desconhecida: ${toolName}` };
      }
    } catch (error) {
      console.error(`Erro ao executar ferramenta ${toolName}:`, error);
      return { success: false, error: error.message || String(error) };
    }
  }

  // --- Active Tab Injections & Messaging ---
  async function getActiveTab() {
    const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
    if (!tabs || tabs.length === 0) {
      throw new Error('Nenhuma aba ativa encontrada.');
    }
    return tabs[0];
  }

  async function ensureContentScriptInjected(tabId) {
    try {
      await chrome.tabs.sendMessage(tabId, { action: 'PING' });
    } catch (e) {
      try {
        await chrome.scripting.insertCSS({ target: { tabId }, files: ['sidepanel/ai/content/content-style.css'] });
        await chrome.scripting.executeScript({ target: { tabId }, files: ['sidepanel/ai/content/content-script.js'] });
        await new Promise(res => setTimeout(res, 120));
      } catch (injErr) {
        console.warn('Não foi possível injetar content script:', injErr);
        throw new Error(`Esta página não permite injeção de scripts (ex: chrome://, brave:// ou página de configurações). Erro: ${injErr.message}`);
      }
    }
  }

  async function executeInActiveTab(action, payload) {
    const tab = await getActiveTab();
    if (tab.url?.startsWith('chrome://') || tab.url?.startsWith('brave://') || tab.url?.startsWith('edge://')) {
      return { success: false, error: 'Não é permitido inspecionar páginas internas protegidas do navegador.' };
    }

    await ensureContentScriptInjected(tab.id);
    const response = await chrome.tabs.sendMessage(tab.id, { action, payload });
    return response;
  }

  // --- Screenshots ---
  async function captureScreenshot() {
    const dataUrl = await chrome.tabs.captureVisibleTab(null, { format: 'png' });
    return { success: true, message: 'Captura de tela realizada com sucesso', dataUrlPreview: dataUrl.slice(0, 100) + '...' };
  }

  // --- Tab Management Functions ---
  async function listTabs(args = {}) {
    const query = args.current_window_only ? { currentWindow: true } : {};
    const tabs = await chrome.tabs.query(query);
    return {
      success: true,
      total: tabs.length,
      tabs: tabs.map(t => ({
        id: t.id, windowId: t.windowId, title: t.title, url: t.url, active: t.active,
        pinned: t.pinned, muted: t.mutedInfo?.muted || false, audible: t.audible || false, groupId: t.groupId
      }))
    };
  }

  async function switchTab(tabId) {
    const tab = await chrome.tabs.get(tabId);
    await chrome.tabs.update(tabId, { active: true });
    if (tab.windowId) await chrome.windows.update(tab.windowId, { focused: true });
    return { success: true, message: `Foco alterado para a aba: "${tab.title}"` };
  }

  async function createTab(url, active = true) {
    const tab = await chrome.tabs.create({ url, active });
    return { success: true, tabId: tab.id, message: `Nova aba criada: ${url}` };
  }

  async function closeTabs(tabIds) {
    if (!Array.isArray(tabIds) || tabIds.length === 0) {
      return { success: false, error: 'Lista de tab_ids vazia ou inválida.' };
    }
    await chrome.tabs.remove(tabIds);
    return { success: true, message: `${tabIds.length} aba(s) fechada(s) com sucesso.` };
  }

  async function duplicateTab(tabId) {
    const tab = await chrome.tabs.duplicate(tabId);
    return { success: true, newTabId: tab.id, message: `Aba ${tabId} duplicada com sucesso.` };
  }

  async function pinTab(tabId, pinned) {
    await chrome.tabs.update(tabId, { pinned });
    return { success: true, message: `Aba ${tabId} ${pinned ? 'fixada' : 'desafixada'}.` };
  }

  async function muteTab(tabId, muted) {
    await chrome.tabs.update(tabId, { muted });
    return { success: true, message: `Áudio da aba ${tabId} ${muted ? 'silenciado' : 'reativado'}.` };
  }

  async function groupTabs(tabIds, title, color = 'blue') {
    const groupId = await chrome.tabs.group({ tabIds });
    const updateData = {};
    if (title) updateData.title = title;
    if (color) updateData.color = color;
    await chrome.tabGroups.update(groupId, updateData);
    return { success: true, groupId, message: `Abas agrupadas no grupo "${title || 'Novo Grupo'}" com a cor ${color}.` };
  }

  async function setZoom(zoomFactor, tabId) {
    let targetTabId = tabId;
    if (!targetTabId) {
      const active = await getActiveTab();
      targetTabId = active.id;
    }
    await chrome.tabs.setZoom(targetTabId, zoomFactor);
    return { success: true, message: `Nível de zoom ajustado para ${Math.round(zoomFactor * 100)}%.` };
  }

  // --- History & Bookmarks Functions ---
  async function searchHistory(text, maxResults = 15, startDaysAgo = 7) {
    const startTime = Date.now() - (startDaysAgo * 24 * 60 * 60 * 1000);
    const results = await chrome.history.search({ text: text || '', startTime, maxResults: maxResults || 15 });
    return {
      success: true,
      total: results.length,
      results: results.map(r => ({
        title: r.title, url: r.url,
        lastVisitTime: new Date(r.lastVisitTime).toLocaleString('pt-BR'),
        visitCount: r.visitCount
      }))
    };
  }

  async function deleteHistoryUrl(url) {
    await chrome.history.deleteUrl({ url });
    return { success: true, message: `URL removida do histórico: ${url}` };
  }

  async function searchBookmarks(query) {
    const results = await chrome.bookmarks.search(query);
    return {
      success: true,
      total: results.length,
      bookmarks: results.slice(0, 20).map(b => ({
        id: b.id, title: b.title, url: b.url,
        dateAdded: b.dateAdded ? new Date(b.dateAdded).toLocaleString('pt-BR') : undefined
      }))
    };
  }

  async function createBookmark(title, url, parentId) {
    const bookmarkData = { title, url };
    if (parentId) bookmarkData.parentId = parentId;
    const bookmark = await chrome.bookmarks.create(bookmarkData);
    return { success: true, bookmarkId: bookmark.id, message: `Favorito "${title}" salvo com sucesso.` };
  }

  async function getTopSites() {
    const sites = await chrome.topSites.get();
    return { success: true, sites: sites.slice(0, 10).map(s => ({ title: s.title, url: s.url })) };
  }

  // --- Extensions Management ---
  async function listExtensions() {
    if (!chrome.management) return { success: false, error: 'API de gerenciamento de extensões indisponível.' };
    const items = await chrome.management.getAll();
    return {
      success: true,
      total: items.length,
      extensions: items
        .filter(i => i.type === 'extension')
        .map(i => ({ id: i.id, name: i.name, version: i.version, enabled: i.enabled, mayDisable: i.mayDisable }))
    };
  }

  async function setExtensionEnabled(extensionId, enabled) {
    if (!chrome.management) return { success: false, error: 'API de gerenciamento de extensões indisponível.' };
    await chrome.management.setEnabled(extensionId, !!enabled);
    return { success: true, message: `Extensão ${extensionId} ${enabled ? 'ativada' : 'desativada'}.` };
  }

  async function uninstallExtension(extensionId) {
    if (!chrome.management) return { success: false, error: 'API de gerenciamento de extensões indisponível.' };
    await chrome.management.uninstall(extensionId, { showConfirmDialog: true });
    return { success: true, message: `Solicitação de desinstalação enviada para ${extensionId}.` };
  }

  // --- Privacy & Browsing Data Functions ---
  async function clearBrowsingData(timeframe, dataTypes = ['cache', 'cookies', 'formData']) {
    let since = 0;
    const now = Date.now();
    switch (timeframe) {
      case 'last_hour': since = now - (60 * 60 * 1000); break;
      case 'last_day': since = now - (24 * 60 * 60 * 1000); break;
      case 'last_week': since = now - (7 * 24 * 60 * 60 * 1000); break;
      case 'last_month': since = now - (30 * 24 * 60 * 60 * 1000); break;
      case 'all_time': default: since = 0; break;
    }

    const dataRemoval = {};
    dataTypes.forEach(type => {
      if (type === 'cache') dataRemoval.cache = true;
      if (type === 'cookies') dataRemoval.cookies = true;
      if (type === 'downloads') dataRemoval.downloads = true;
      if (type === 'history') dataRemoval.history = true;
      if (type === 'formData') dataRemoval.formData = true;
      if (type === 'passwords') dataRemoval.passwords = true;
    });

    await chrome.browsingData.remove({ since }, dataRemoval);
    return { success: true, message: `Dados de navegação limpos com sucesso (${dataTypes.join(', ')} para o período: ${timeframe}).` };
  }

  async function getPrivacySettings() {
    const settings = {};
    try {
      const doNotTrack = await new Promise(r => chrome.privacy.websites.doNotTrackEnabled.get({}, r));
      settings.doNotTrack = doNotTrack?.value;
      const thirdParty = await new Promise(r => chrome.privacy.websites.thirdPartyCookiesAllowed.get({}, r));
      settings.thirdPartyCookiesAllowed = thirdParty?.value;
      const autofillAddr = await new Promise(r => chrome.privacy.services.autofillAddressEnabled.get({}, r));
      settings.autofillAddress = autofillAddr?.value;
      const networkPred = await new Promise(r => chrome.privacy.network.networkPredictionEnabled.get({}, r));
      settings.networkPrediction = networkPred?.value;
    } catch (e) {
      settings.warning = 'Algumas configurações de privacidade podem ser gerenciadas pelo Brave Shields.';
    }
    return { success: true, settings };
  }

  async function setPrivacySetting(settingName, value) {
    try {
      if (settingName === 'doNotTrack') {
        await new Promise((res, rej) => chrome.privacy.websites.doNotTrackEnabled.set({ value }, () => chrome.runtime.lastError ? rej(chrome.runtime.lastError) : res()));
      } else if (settingName === 'thirdPartyCookies') {
        await new Promise((res, rej) => chrome.privacy.websites.thirdPartyCookiesAllowed.set({ value }, () => chrome.runtime.lastError ? rej(chrome.runtime.lastError) : res()));
      } else if (settingName === 'autofillAddress') {
        await new Promise((res, rej) => chrome.privacy.services.autofillAddressEnabled.set({ value }, () => chrome.runtime.lastError ? rej(chrome.runtime.lastError) : res()));
      } else if (settingName === 'networkPrediction') {
        await new Promise((res, rej) => chrome.privacy.network.networkPredictionEnabled.set({ value }, () => chrome.runtime.lastError ? rej(chrome.runtime.lastError) : res()));
      }
      return { success: true, message: `Configuração de privacidade '${settingName}' alterada para ${value}.` };
    } catch (err) {
      return { success: false, error: err.message || 'Falha ao alterar configuração de privacidade.' };
    }
  }

  async function getContentSettings(contentType) {
    const activeTab = await getActiveTab();
    if (!chrome.contentSettings || !chrome.contentSettings[contentType]) {
      return { success: false, error: `Recurso contentSettings para '${contentType}' não suportado.` };
    }
    const result = await new Promise(r => { chrome.contentSettings[contentType].get({ primaryUrl: activeTab.url || 'http://*/*' }, r); });
    return { success: true, contentType, setting: result?.setting, primaryUrl: activeTab.url };
  }

  async function setContentSettings(contentType, setting, scope = 'current_site') {
    if (!chrome.contentSettings || !chrome.contentSettings[contentType]) {
      return { success: false, error: `Recurso contentSettings para '${contentType}' não suportado.` };
    }
    const activeTab = await getActiveTab();
    let primaryPattern = '<all_urls>';
    if (scope === 'current_site' && activeTab.url) {
      try {
        const urlObj = new URL(activeTab.url);
        primaryPattern = `${urlObj.protocol}//${urlObj.hostname}/*`;
      } catch (e) {
        primaryPattern = '<all_urls>';
      }
    }
    await new Promise((res, rej) => {
      chrome.contentSettings[contentType].set({ primaryPattern, setting }, () => chrome.runtime.lastError ? rej(chrome.runtime.lastError) : res());
    });
    return { success: true, message: `Permissão de '${contentType}' definida como '${setting}' para o padrão: ${primaryPattern}` };
  }

  // --- Downloads ---
  async function downloadFile(filename, content, url) {
    let downloadUrl = url;
    if (content && !url) {
      const encoded = encodeURIComponent(content);
      downloadUrl = `data:text/plain;charset=utf-8,${encoded}`;
    }
    if (!downloadUrl) {
      return { success: false, error: 'Forneça uma URL ou o conteúdo de texto para download.' };
    }
    const downloadId = await chrome.downloads.download({ url: downloadUrl, filename, saveAs: false });
    return { success: true, downloadId, filename, message: `Download do arquivo '${filename}' iniciado.` };
  }

  async function searchDownloads(query, limit = 10) {
    const items = await chrome.downloads.search({ query: query || undefined, limit: limit || 10, orderBy: ['-startTime'] });
    return {
      success: true,
      total: items.length,
      downloads: items.map(d => ({
        id: d.id, filename: d.filename, url: d.url, state: d.state, fileSize: d.fileSize,
        startTime: d.startTime ? new Date(d.startTime).toLocaleString('pt-BR') : undefined
      }))
    };
  }

  global.SidebarAI = global.SidebarAI || {};
  global.SidebarAI.executeTool = executeTool;
})(window);
